// Renders the mesh defined by iChannel0 coords.

float sdLine(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p-a, ba = b-a;
    float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
    return length( pa - ba*h );
}

float sdBox(vec2 p, vec2 a, vec2 b) {
    vec2 d = abs(p - (b + a)*0.5) - (b - a)*0.5;
    return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}

vec2 p2q(vec2 p) {
    vec2 ar = iResolution.xy/iResolution.yy;
    return (p/iResolution.xy*2. - 1.) * ar;
}

vec2 q2p(vec2 q) {
    vec2 ar = iResolution.xy/iResolution.yy;
    return (q/ar*0.5 + 0.5) * iResolution.xy;
}

vec2 pos(int i) {
    return str(iChannel0, ivec2(i,0)).xy;
}

vec3 sdf(vec2 q) {
    int N = texSize(iChannel0);
    float d = 0.05, d1 = d;

    vec4 box = texelFetch(iChannel2, ivec2(0), 0);
    float d0 = sdBox(q, box.xy, box.zw);
    if (d0 > d) return vec3(d);

    for (int j = 0; j*GS < N; j++) {
        vec4 box = texelFetch(iChannel1, ivec2(j, 0), 0);
        float db = sdBox(q, box.xy, box.zw);
        if (db > d) continue;
        d1 = min(d1, abs(db));

        vec2 a = pos(j*GS);
        for (int i = 1; i <= GS; i++) {
            vec2 b = pos(j*GS + i);
            d = min(d, sdLine(q, a, b));
            a = b;
        }        
    }


    return vec3(d, abs(d0), d1);
}

void mainImage(out vec4 o, vec2 p) {
    vec2 q = p2q(p);
    vec3 d = sdf(q/R1);

    o = vec4(1);
    o.rgb *= 1.0 - 1.0*exp(-pow(d.x/GLOW, 2.0));
    o.rgb *= 1.0 - 0.2*exp(-pow(d.y/GLOW, 2.0));
    o.rgb *= 1.0 - 0.2*exp(-pow(d.z/GLOW, 2.0));
    o.rgb = pow(o.rgb, vec3(0.4545));

}

const float PI = radians(180.);
const float SQ3 = sqrt(3.);
const float INF = 1e10;

// Simulation consts
const int N_MAX = 512;
const int GS = 32;
const float MASS = 10.0;
const float S2 = 25.0; // u_tt + S2*u = u_xx

// Rendering consts
const vec3 RGB_1 = vec3(0.2, 0.1, 1.5);
const vec3 RGB_2 = vec3(1.5, 0.5, 0.2);
const float GLOW = 0.025;
const float R0 = 0.025;
const float R1 = 0.5;

int texSize(sampler2D ch0) {
    return min(N_MAX, textureSize(ch0, 0).x);
}

vec4 str(sampler2D ch0, ivec2 p) {
    int N = texSize(ch0);
    p.x = (p.x + N) % N;
    return texelFetch(ch0, p, 0);
}

vec4 texFetch(sampler2D ch0, ivec2 p) {
    int N = texSize(ch0);
    p = ivec2(mod(vec2(p), vec2(ivec2(N,2))));
    return texelFetch(ch0, p, 0);
}

// Simulates the motion of masses in iChannel0.
// .xy=curr, .zw=prev

vec2 ring(float px, int N) {
   float phi = 2.*PI*float(px)/float(N);
   return vec2(sin(phi), -cos(phi));
}

vec2 pos0(float px, int N) {
   float phi = 2.*PI*float(px)/float(N);
   vec2 r = ring(px, N);
   r += vec2(0,1) * exp(-pow((phi-PI)*5.0, 2.0));
   return r;
}

void mainImage(out vec4 o, in vec2 p) {
    int N = texSize(iChannel0);
    ivec2 pp = ivec2(p);

    if (pp.x >= N)
        return;

    if (iFrame < 15) {
        o.xy = pos0(p.x, N);
        o.zw = normalize(o.xy);
        return;
    }

    vec4 cc = str(iChannel0, pp);
    vec2 rr = str(iChannel0, pp + ivec2(1,0)).xy;
    vec2 ll = str(iChannel0, pp - ivec2(1,0)).xy;

    vec2 T = rr + ll - 2.*cc.xy; // Hooke's law
    T -= S2*(cc.xy - ring(p.x, N));
    vec2 ds = cc.xy - cc.zw + T/MASS;
    o.xy = cc.xy + ds;
    o.zw = cc.xy; // prev <- curr
}

// iChannel1[x,0] = boundary box for iChannel0[x*GS..(x+1)*GS,0].xy

vec2 str(int i) {
    return texFetch(iChannel0, ivec2(i, 0)).xy;
}

void mainImage( out vec4 o, in vec2 p ) {
    int N = texSize(iChannel0);
    ivec2 pp = ivec2(p);

    if (pp.y > 0 || pp.x*GS >= N) discard;

    o.xy = vec2(+INF); // min
    o.zw = vec2(-INF); // max

    for (int i = pp.x*GS; i <= pp.x*GS + GS; i++) {
        vec2 a = str(i);
        o.xy = min(o.xy, a);
        o.zw = max(o.zw, a);
    }
}

// iChannel2[0,0] = (xy, zw) boundary box of the entire iChannel0.xy

void mainImage( out vec4 o, in vec2 p ) {
    int N = texSize(iChannel1);
    ivec2 pp = ivec2(p);

    if (pp.y > 0 || pp.x > 0) discard;

    o.xy = vec2(+INF); // min
    o.zw = vec2(-INF); // max

    for (int i = 0; i*GS < N; i++) {
        vec4 b = texelFetch(iChannel1, ivec2(i,0), 0);
        o.xy = min(o.xy, b.xy);
        o.zw = max(o.zw, b.zw);
    }
}
